            FfiConverterString.write(voterJid, into: &buf)
            FfiConverterSequenceString.write(selectedOptions, into: &buf)
            FfiConverterTypeAuroraPollTally.write(tally, into: &buf)
            
        
        case let .callReceived(call):
            writeInt(&buf, Int32(11))
